  "e1" [label=<<table border="0" cellborder="0" cellspacing="1" cellpadding="0"><tr><td cellpadding="0"><font point-size="9" color="#0000fe">EVIDENCE</font></td></tr><tr><td cellpadding="0" height="3"></td></tr><tr><td cellpadding="1">Cloud is building</td></tr></table>>, fillcolor="#000101", color="#000201"];
  "s1" [label=<<table border="0" cellborder="0" cellspacing="1" cellpadding="0"><tr><td cellpadding="0"><font point-size="9" color="#0000fe">SOURCE</font></td></tr><tr><td cellpadding="0" height="3"></td></tr><tr><td cellpadding="1">Radar</td></tr></table>>, fillcolor="#000102", color="#000202"];
  "s2" [label=<<table border="0" cellborder="0" cellspacing="1" cellpadding="0"><tr><td cellpadding="0"><font point-size="9" color="#0000fe">SOURCE</font></td></tr><tr><td cellpadding="0" height="3"></td></tr><tr><td cellpadding="1">Satellite</td></tr></table>>, fillcolor="#000102", color="#000202"];
  "c2" [label=<<table border="0" cellborder="0" cellspacing="1" cellpadding="0"><tr><td cellpadding="0"><font point-size="9" color="#0000fe">CLAIM</font></td></tr><tr><td cellpadding="0" height="3"></td></tr><tr><td cellpadding="1">Wind &amp; rain &lt;together&gt;</td></tr></table>>, fillcolor="#000100", color="#000200"];
  "x" [label=<<table border="0" cellborder="0" cellspacing="1" cellpadding="0"><tr><td cellpadding="1">No kind</td></tr></table>>, fillcolor="#000163", color="#000263"];
  { rank=same; "s1"; "s2"; }
  "c1" -> "e1" [label="supported by", color="#000300", fontcolor="#000400"];
  "e1" -> "s1" [label="from", color="#000301", fontcolor="#000401"];
  "e1" -> "s2" [label="from", color="#000301", fontcolor="#000401"];
  "c2" -> "c1" [label="counts against", color="#000302", fontcolor="#000402"];
